begin;
select no_plan();
select ok(has_function_privilege('authenticated','public.get_own_group_membership_context(uuid,uuid)','execute'),'authenticated exact-self read');
select ok(not has_function_privilege(r,'public.get_own_group_membership_context(uuid,uuid)','execute'),r||' denied exact-self read') from unnest(array['anon','service_role']) r;
select ok(prosecdef and proconfig @> array['search_path=""'],'fixed privileged search path') from pg_proc where oid='public.get_own_group_membership_context(uuid,uuid)'::regprocedure;
insert into auth.users(id,email) select ('e7b00000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'grp03b-tap-'||n||'@planets.invalid' from generate_series(1,3) n;
insert into public.profiles(id,display_name) select id,case when email='grp03b-tap-3@planets.invalid' then null else 'Fictional self context' end from auth.users where email like 'grp03b-tap-%';
insert into private.community_groups(id,name,description,group_kind,volunteering_focus,publication_state,original_actor_id)
values('e7b10000-0000-4000-8000-000000000001','Private fictional draft','A private fictional group draft description.','informal',false,'draft','e7b00000-0000-4000-8000-000000000001');
insert into private.community_group_managers(group_id,profile_id,appointed_by_actor_id) values('e7b10000-0000-4000-8000-000000000001','e7b00000-0000-4000-8000-000000000001','e7b00000-0000-4000-8000-000000000001');
insert into private.group_join_requests(id,group_id,requester_id,note) values('e7b20000-0000-4000-8000-000000000001','e7b10000-0000-4000-8000-000000000001','e7b00000-0000-4000-8000-000000000002','Private exact-self note');
set local role authenticated;
select set_config('request.jwt.claim.sub','e7b00000-0000-4000-8000-000000000002',true);
select is((select pending_request_id from public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000002','e7b10000-0000-4000-8000-000000000001')),'e7b20000-0000-4000-8000-000000000001'::uuid,'exact pending request even with private unavailable content');
select is((select pending_note from public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000002','e7b10000-0000-4000-8000-000000000001')),'Private exact-self note','only own pending note');
select is((select current_membership_id from public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000002','e7b10000-0000-4000-8000-000000000001')),null::uuid,'request does not manufacture membership');
select throws_ok($$select public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000001','e7b10000-0000-4000-8000-000000000001')$$,'42501',null,'cannot choose another identity');
select public.withdraw_group_join_request('e7b00000-0000-4000-8000-000000000002','e7b20000-0000-4000-8000-000000000001',gen_random_uuid());
select is((select pending_request_id from public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000002','e7b10000-0000-4000-8000-000000000001')),null::uuid,'withdrawn request is not pending');
select is((select latest_request_status from public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000002','e7b10000-0000-4000-8000-000000000001')),'withdrawn','retains latest own state');
select set_config('request.jwt.claim.sub','e7b00000-0000-4000-8000-000000000001',true);
select is((select authority_role from public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000001','e7b10000-0000-4000-8000-000000000001')),'creator','Creator own draft authority retained');
select is((select pending_note from public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000001','e7b10000-0000-4000-8000-000000000001')),null::text,'manager exact-self projection cannot disclose applicant note');
select set_config('request.jwt.claim.sub','e7b00000-0000-4000-8000-000000000003',true);
select lives_ok($$select public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000003','e7b10000-0000-4000-8000-000000000001')$$,'incomplete profile can inspect own exit state');
select is((select authority_role from public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000003','e7b10000-0000-4000-8000-000000000001')),null::text,'unrelated identity has no authority');
reset role;
delete from public.profiles where id='e7b00000-0000-4000-8000-000000000003';
set local role authenticated;
select throws_ok($$select public.get_own_group_membership_context('e7b00000-0000-4000-8000-000000000003','e7b10000-0000-4000-8000-000000000001')$$,'42501',null,'absent identity fails closed');
select * from finish();
rollback;
